// hooks/useLibOpenMPT.ts

import { useState, useRef, useCallback, useEffect } from 'react';
import {
    ModuleInfo,
    NoteData,
    PatternData,
    SongPosition,
} from '../types';

// The path to our new worklet wrapper
const workletURL = '/openmpt-processor.js';

export const useLibOpenMPT = () => {
    const [isReady, setIsReady] = useState(false);
    const [moduleInfo, setModuleInfo] = useState<ModuleInfo | null>(null);
    const [songPosition, setSongPosition] = useState<SongPosition | null>(null);
    const [currentPattern, setCurrentPattern] = useState<PatternData | null>(null);
    const [currentNote, setCurrentNote] = useState<NoteData | null>(null);
    const [isPlaying, setIsPlaying] = useState(false);

    // Refs for audio context and worklet node
    const audioContextRef = useRef<AudioContext | null>(null);
    const workletNodeRef = useRef<AudioWorkletNode | null>(null);

    // Effect to initialize the AudioWorklet
    useEffect(() => {
        const initAudioWorklet = async () => {
            try {
                const context = new (window.AudioContext ||
                    (window as any).webkitAudioContext)();
                audioContextRef.current = context;

                await context.audioWorklet.addModule(workletURL);

                const workletNode = new AudioWorkletNode(
                    context,
                    'openmpt-processor',
                );
                workletNode.connect(context.destination);
                workletNodeRef.current = workletNode;

                // Set up listener for messages FROM the worklet
                workletNode.port.onmessage = (event) => {
                    const { type, data } = event.data;
                    switch (type) {
                        case 'ready':
                            setIsReady(true);
                            break;
                        case 'metadata':
                            setModuleInfo(data);
                            break;
                        case 'update':
                            setSongPosition(data.position);
                            setCurrentPattern(data.pattern);
                            // You can derive currentNote from pattern data if needed
                            // For simplicity, this example just passes the main data
                            break;
                        case 'error':
                            console.error('AudioWorklet Error:', data);
                            // Handle error state in React
                            break;
                    }
                };
            } catch (e) {
                console.error('Failed to initialize AudioWorklet:', e);
            }
        };

        initAudioWorklet();

        // Cleanup
        return () => {
            audioContextRef.current?.close();
        };
    }, []);

    // Function to send commands TO the worklet
    const postWorkletMessage = (type: string, data?: any) => {
        if (!workletNodeRef.current) return;

        // For 'load', we need to transfer the ArrayBuffer
        if (type === 'load' && data instanceof ArrayBuffer) {
            workletNodeRef.current.port.postMessage({ type, data }, [data]);
        } else {
            workletNodeRef.current.port.postMessage({ type, data });
        }
    };

    const loadModule = useCallback(async (file: File) => {
        if (!isReady || !workletNodeRef.current) return;

        try {
            const arrayBuffer = await file.arrayBuffer();
            // Send the ArrayBuffer to the worklet to be loaded
            postWorkletMessage('load', arrayBuffer);
            setIsPlaying(false);
        } catch (e) {
            console.error(e);
        }
    }, [isReady]);

    const play = useCallback(() => {
        if (!moduleInfo || !audioContextRef.current) return;

        // Browsers require user interaction to start audio
        audioContextRef.current.resume();

        postWorkletMessage('play');
        setIsPlaying(true);
    }, [moduleInfo]);

    const pause = useCallback(() => {
        if (!moduleInfo) return;
        postWorkletMessage('pause');
        setIsPlaying(false);
    }, [moduleInfo]);

    const stop = useCallback(() => {
        if (!moduleInfo) return;
        postWorkletMessage('stop');
        setIsPlaying(false);
    }, [moduleInfo]);

    const seek = useCallback((position: number) => {
        if (!moduleInfo) return;
        postWorkletMessage('seek', position);
    }, [moduleInfo]);

    // This is no longer needed, as updates are pushed from the worklet
    // const startUpdating = () => { ... }
    // const stopUpdating = () => { ... }

    return {
        isReady,
        moduleInfo,
        songPosition,
        currentPattern,
        currentNote,
        isPlaying,
        loadModule,
        play,
        pause,
        stop,
        seek,
    };
};

// hooks/useLibOpenMPT.ts

import { useState, useRef, useCallback, useEffect } from 'react';
import {
    ModuleInfo,
    NoteData,
    PatternData,
    SongPosition,
} from '../types';

// The path to our new worklet wrapper
const workletURL = '/openmpt-processor.js';

export const useLibOpenMPT = () => {
    const [isReady, setIsReady] = useState(false);
    const [moduleInfo, setModuleInfo] = useState<ModuleInfo | null>(null);
    const [songPosition, setSongPosition] = useState<SongPosition | null>(null);
    const [currentPattern, setCurrentPattern] = useState<PatternData | null>(null);
    const [currentNote] = useState<NoteData | null>(null);
    const [isPlaying, setIsPlaying] = useState(false);

    // Added states for missing properties
    const [status, _setStatus] = useState<string>('idle');
    const [isModuleLoaded, setIsModuleLoaded] = useState<boolean>(false);
    const [aiResponse, setAiResponse] = useState<string>('');
    const [isAiLoading, setIsAiLoading] = useState<boolean>(false);
    const [sequencerMatrix, _setSequencerMatrix] = useState<any>(null);
    const [sequencerCurrentRow, _setSequencerCurrentRow] = useState<number>(0);
    const [sequencerGlobalRow, _setSequencerGlobalRow] = useState<number>(0);
    const [totalPatternRows, _setTotalPatternRows] = useState<number>(0);

    // Refs for audio context and worklet node
    const audioContextRef = useRef<AudioContext | null>(null);
    const workletNodeRef = useRef<AudioWorkletNode | null>(null);

    // Effect to initialize the AudioWorklet
    useEffect(() => {
        const initAudioWorklet = async () => {
            try {
                const context = new (window.AudioContext ||
                    (window as any).webkitAudioContext)();
                audioContextRef.current = context;

                await context.audioWorklet.addModule(workletURL);

                const workletNode = new AudioWorkletNode(
                    context,
                    'openmpt-processor',
                );
                workletNode.connect(context.destination);
                workletNodeRef.current = workletNode;

                // Set up listener for messages FROM the worklet
                workletNode.port.onmessage = (event) => {
                    const { type, data } = event.data;
                    switch (type) {
                        case 'ready':
                            setIsReady(true);
                            break;
                        case 'metadata':
                            setModuleInfo(data);
                            setIsModuleLoaded(true);
                            break;
                        case 'update':
                            setSongPosition(data.position);
                            setCurrentPattern(data.pattern);
                            // You can derive currentNote from pattern data if needed
                            // For simplicity, this example just passes the main data
                            break;
                        case 'error':
                            console.error('AudioWorklet Error:', data);
                            // Handle error state in React
                            break;
                    }
                };
            } catch (e) {
                console.error('Failed to initialize AudioWorklet:', e);
            }
        };

        initAudioWorklet();

        // Cleanup
        return () => {
            audioContextRef.current?.close();
        };
    }, []);

    // Function to send commands TO the worklet
    const postWorkletMessage = (type: string, data?: any) => {
        if (!workletNodeRef.current) return;

        // For 'load', we need to transfer the ArrayBuffer
        if (type === 'load' && data instanceof ArrayBuffer) {
            workletNodeRef.current.port.postMessage({ type, data }, [data]);
        } else {
            workletNodeRef.current.port.postMessage({ type, data });
        }
    };

    const loadModule = useCallback(async (file: File) => {
        if (!isReady || !workletNodeRef.current) return;

        try {
            const arrayBuffer = await file.arrayBuffer();
            // Send the ArrayBuffer to the worklet to be loaded
            postWorkletMessage('load', arrayBuffer);
            setIsPlaying(false);
        } catch (e) {
            console.error(e);
        }
    }, [isReady]);

    const play = useCallback(() => {
        if (!moduleInfo || !audioContextRef.current) return;

        // Browsers require user interaction to start audio
        audioContextRef.current.resume();

        postWorkletMessage('play');
        setIsPlaying(true);
    }, [moduleInfo]);

    const pause = useCallback(() => {
        if (!moduleInfo) return;
        postWorkletMessage('pause');
        setIsPlaying(false);
    }, [moduleInfo]);

    const stop = useCallback(() => {
        if (!moduleInfo) return;
        postWorkletMessage('stop');
        setIsPlaying(false);
    }, [moduleInfo]);

    const seek = useCallback((position: number) => {
        if (!moduleInfo) return;
        postWorkletMessage('seek', position);
    }, [moduleInfo]);

    const stopMusic = useCallback(() => {
        stop();
    }, [stop]);

    const askAI = useCallback(async (query?: string) => {
        if (!moduleInfo) return;
        setIsAiLoading(true);
        try {
            // Implement AI call here, e.g., using Gemini API
            const response = await fetch('/api/ask-ai', { method: 'POST', body: JSON.stringify({ query, module: moduleInfo }) });
            const data = await response.json();
            setAiResponse(data.response);
        } catch (e) {
            console.error(e);
            setAiResponse('Error fetching AI response');
        } finally {
            setIsAiLoading(false);
        }
    }, [moduleInfo]);

    const seekToStep = useCallback((step: number) => {
        // Implement seek to step logic
        postWorkletMessage('seekToStep', step);
    }, []);

    // This is no longer needed, as updates are pushed from the worklet
    // const startUpdating = () => { ... }
    // const stopUpdating = () => { ... }

    return {
        isReady,
        moduleInfo,
        songPosition,
        currentPattern,
        currentNote,
        isPlaying,
        loadModule,
        play,
        pause,
        stop,
        seek,
        status,
        isModuleLoaded,
        aiResponse,
        isAiLoading,
        stopMusic,
        askAI,
        sequencerMatrix,
        sequencerCurrentRow,
        sequencerGlobalRow,
        totalPatternRows,
        seekToStep,
    };
};

export interface ModuleInfo {
  title: string;
  order: number;
  row: number;
  bpm: number;
  numChannels: number;
}

// Media types for images/GIFs/videos used by the UI
export type MediaKind = 'image' | 'gif' | 'video';

export interface MediaItem {
  /** stable id for the item (uuid or timestamp string) */
  id: string;
  /** Object URL or remote URL to the media resource */
  url: string;
  /** Original file name or URL filename for display */
  fileName?: string;
  /** MIME type (e.g. image/png, image/gif, video/mp4) */
  mimeType?: string;
  /** Derived kind: 'image' | 'gif' | 'video' */
  kind: MediaKind;
  /** Rendering prefs */
  loop?: boolean; // defaults: false for images, true for gifs, false for video
  muted?: boolean; // sensible default: true for autoplay overlays
  fit?: 'contain' | 'cover';
  /** Creation timestamp */
  createdAt?: number;
  /** Whether this url was created from a local File via URL.createObjectURL */
  isObjectUrl?: boolean;
}

export interface MediaState {
  media: MediaItem[];
  activeMediaId?: string;
}

// Pattern matrix cell with parsed information
export interface PatternCell {
  type: 'note' | 'effect' | 'instrument' | 'empty';
  text: string;
}

// Pattern matrix for sequencer visualization: rows x channels cell grid
export interface PatternMatrix {
  order: number;
  patternIndex: number;
  numRows: number;
  numChannels: number;
  // rows[rowIndex][channelIndex] contains parsed cell info
  rows: PatternCell[][];
}

export interface SequencerState {
  matrix: PatternMatrix | null;
  currentRow: number;
}

// A best-effort typing for the Emscripten module object
export interface LibOpenMPT {
  onRuntimeInitialized: () => void;
  HEAPU8: Uint8Array;
  HEAPF32: Float32Array;
  _malloc: (size: number) => number;
  _free: (ptr: number) => void;
  UTF8ToString: (ptr: number) => string;
  stringToUTF8: (str: string) => number;
  _openmpt_module_create_from_memory2: (
    bufferPtr: number,
    fileDataLength: number,
    logfunc: number,
    loguser: number,
    errfunc: number,
    erruser: number,
    error: number,
    error_message: number,
    ctls: number
  ) => number; // returns modulePtr
  _openmpt_module_destroy: (modulePtr: number) => void;
  _openmpt_free_string: (strPtr: number) => void;
  _openmpt_module_get_metadata: (modulePtr: number, keyPtr: number) => number; // returns valuePtr
  _openmpt_module_get_num_orders: (modulePtr: number) => number;
  _openmpt_module_get_num_channels: (modulePtr: number) => number;
  _openmpt_module_get_order_pattern: (modulePtr: number, order: number) => number;
  _openmpt_module_get_num_patterns: (modulePtr: number) => number;
  _openmpt_module_get_pattern_num_rows: (modulePtr: number, pattern: number) => number;
  _openmpt_module_format_pattern_row_channel: (
    modulePtr: number,
    pattern: number,
    row: number,
    channel: number,
    width: number,
    padded: number
  ) => number; // returns strPtr
  _openmpt_module_read_float_stereo: (
    modulePtr: number,
    sampleRate: number,
    count: number,
    leftBufferPtr: number,
    rightBufferPtr: number
  ) => number; // returns frames rendered
  _openmpt_module_set_position_order_row: (modulePtr: number, order: number, row: number) => void;
  _openmpt_module_get_current_order: (modulePtr: number) => number;
  _openmpt_module_get_current_row: (modulePtr: number) => number;
  _openmpt_module_get_position_seconds: (modulePtr: number) => number;
  _openmpt_module_get_current_estimated_bpm: (modulePtr: number) => number;
}

// For the global window object
declare global {
  interface Window {
    libopenmpt: Partial<LibOpenMPT>;
    AudioContext: typeof AudioContext;
    webkitAudioContext: typeof AudioContext;
    GEMINI_API_KEY?: string;
    // FIX: Add promise for robust initialization
    libopenmptReady: Promise<Partial<LibOpenMPT>>;
  }
}

export interface ModuleInfo {
  title: string;
  order: number;
  row: number;
  bpm: number;
  numChannels: number;
}

export interface NoteData {
  // Define based on usage, e.g., note, instrument, etc.
  note?: string;
  instrument?: number;
  effect?: string;
}

export interface PatternData {
  // Define based on usage, e.g., pattern index, rows, etc.
  index: number;
  rows: any[]; // Adjust as needed
}

export interface SongPosition {
  order: number;
  row: number;
  seconds: number;
}

// Media types for images/GIFs/videos used by the UI
export type MediaKind = 'image' | 'gif' | 'video';

export interface MediaItem {
  /** stable id for the item (uuid or timestamp string) */
  id: string;
  /** Object URL or remote URL to the media resource */
  url: string;
  /** Original file name or URL filename for display */
  fileName?: string;
  /** MIME type (e.g. image/png, image/gif, video/mp4) */
  mimeType?: string;
  /** Derived kind: 'image' | 'gif' | 'video' */
  kind: MediaKind;
  /** Rendering prefs */
  loop?: boolean; // defaults: false for images, true for gifs, false for video
  muted?: boolean; // sensible default: true for autoplay overlays
  fit?: 'contain' | 'cover';
  /** Creation timestamp */
  createdAt?: number;
  /** Whether this url was created from a local File via URL.createObjectURL */
  isObjectUrl?: boolean;
}

export interface MediaState {
  media: MediaItem[];
  activeMediaId?: string;
}

// Pattern matrix cell with parsed information
export interface PatternCell {
  type: 'note' | 'effect' | 'instrument' | 'empty';
  text: string;
}

// Pattern matrix for sequencer visualization: rows x channels cell grid
export interface PatternMatrix {
  order: number;
  patternIndex: number;
  numRows: number;
  numChannels: number;
  // rows[rowIndex][channelIndex] contains parsed cell info
  rows: PatternCell[][];
}

export interface SequencerState {
  matrix: PatternMatrix | null;
  currentRow: number;
}

// A best-effort typing for the Emscripten module object
export interface LibOpenMPT {
  onRuntimeInitialized: () => void;
  HEAPU8: Uint8Array;
  HEAPF32: Float32Array;
  _malloc: (size: number) => number;
  _free: (ptr: number) => void;
  UTF8ToString: (ptr: number) => string;
  stringToUTF8: (str: string) => number;
  _openmpt_module_create_from_memory2: (
    bufferPtr: number,
    fileDataLength: number,
    logfunc: number,
    loguser: number,
    errfunc: number,
    erruser: number,
    error: number,
    error_message: number,
    ctls: number
  ) => number; // returns modulePtr
  _openmpt_module_destroy: (modulePtr: number) => void;
  _openmpt_free_string: (strPtr: number) => void;
  _openmpt_module_get_metadata: (modulePtr: number, keyPtr: number) => number; // returns valuePtr
  _openmpt_module_get_num_orders: (modulePtr: number) => number;
  _openmpt_module_get_num_channels: (modulePtr: number) => number;
  _openmpt_module_get_order_pattern: (modulePtr: number, order: number) => number;
  _openmpt_module_get_num_patterns: (modulePtr: number) => number;
  _openmpt_module_get_pattern_num_rows: (modulePtr: number, pattern: number) => number;
  _openmpt_module_format_pattern_row_channel: (
    modulePtr: number,
    pattern: number,
    row: number,
    channel: number,
    width: number,
    padded: number
  ) => number; // returns strPtr
  _openmpt_module_read_float_stereo: (
    modulePtr: number,
    sampleRate: number,
    count: number,
    leftBufferPtr: number,
    rightBufferPtr: number
  ) => number; // returns frames rendered
  _openmpt_module_set_position_order_row: (modulePtr: number, order: number, row: number) => void;
  _openmpt_module_get_current_order: (modulePtr: number) => number;
  _openmpt_module_get_current_row: (modulePtr: number) => number;
  _openmpt_module_get_position_seconds: (modulePtr: number) => number;
  _openmpt_module_get_current_estimated_bpm: (modulePtr: number) => number;
}

// For the global window object
declare global {
  interface Window {
    libopenmpt: Partial<LibOpenMPT>;
    AudioContext: typeof AudioContext;
    webkitAudioContext: typeof AudioContext;
    GEMINI_API_KEY?: string;
    // FIX: Add promise for robust initialization
    libopenmptReady: Promise<Partial<LibOpenMPT>>;
  }
}
